head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL71812";
scwin.form = null;

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — excelCheckList

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil71812.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_DigitalExcelUpload", fn: function(){ return ((((dma_pageContext.get("excelCheckList") ?? "")) && typeof ((dma_pageContext.get("excelCheckList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("excelCheckList") ?? "")).getRowCount() : ((((dma_pageContext.get("excelCheckList") ?? "")) == null) ? 0 : (((dma_pageContext.get("excelCheckList") ?? "")).length || 0))) !==0 && !(String(((dma_pageContext.get("excelCheckList") ?? "")) == null ? '' : ((dma_pageContext.get("excelCheckList") ?? ""))).length === 0)); } }, { id: "btn_DigitalExcelResultDown", fn: function(){ return ((((dma_pageContext.get("excelCheckList") ?? "")) && typeof ((dma_pageContext.get("excelCheckList") ?? "")).getRowCount === 'function' ? ((dma_pageContext.get("excelCheckList") ?? "")).getRowCount() : ((((dma_pageContext.get("excelCheckList") ?? "")) == null) ? 0 : (((dma_pageContext.get("excelCheckList") ?? "")).length || 0))) !==0 && !(String(((dma_pageContext.get("excelCheckList") ?? "")) == null ? '' : ((dma_pageContext.get("excelCheckList") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_DigitalExcelUpload_onclick
 * @description 「업로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_DigitalExcelUpload_onclick = function(e){
    try {
        scwin.digitalExcelUpload()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71812.btn_DigitalExcelUpload_onclick' }); }
};

/**
 * @method
 * @name btn_DigitalExcelResultDown_onclick
 * @description 「검증결과다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_DigitalExcelResultDown_onclick = async function(e){
    try {
        await scwin.digitalExcelResultDown()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil71812.btn_DigitalExcelResultDown_onclick' }); }
};

/**
 * @method
 * @name btn_closePop_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_closePop_onclick = function(e){
    try {
        scwin.close_pop()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil71812.btn_closePop_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_DigitalExcelResultDown
 * @description Digital Excel Result Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_DigitalExcelResultDown = async function () {
    const sbmOptions = {
        id: "tx_fn_DigitalExcelResultDown",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_DigitalExcelResultDownReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/digital/DigitalList.do",
        ref: "dma_loadListReq",
        target: "",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        {
            const d = $c.util.getComponent("dlt_excelCheckList");
            const a = (res && res.responseJSON && res.responseJSON.body && res.responseJSON.body.content) || [];
            if (!d || !d.setJSON) { /* TODO Stage2: [sdd] 구분자 열 채우기 대상 없음: dlt_excelCheckList */ }
            else { d.setJSON(a.map(function (v) {
                            const p = String(v == null ? '' : (v && v.value !== undefined ? v.value : v)).split("&@!&");
                            return { c0: p[0] || '', c1: p[1] || '', c2: p[2] || '', c3: p[3] || '', c4: p[4] || '' };
                })); }
        }
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name close_pop
 * @description close pop 처리
 * @returns {void}
 * @hidden N
 */
scwin.close_pop = function () {
    $c.win.setPageFrameSrc(null, '/ui/jsp/JLDFIL71501.xml', { method: "searchList", listBzCd: "3" });
    $c.win.closePopup();
};

/**
 * @method
 * @name digitalExcelUpload
 * @description digital Excel Upload 처리
 * @returns {void}
 * @hidden N
 */
scwin.digitalExcelUpload = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), "/ui/jsp/JLDFIL71811.xml");
};

/**
 * @method
 * @name digitalExcelResultDown
 * @description digital Excel Result Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.digitalExcelResultDown = async function () {
    scwin.form = (document.digitallistResultDownForm || { elements: [] });
    scwin.form.action = '/digital/DigitalList.do';
    $c.util.getComponent('dma_DigitalExcelResultDownReq').set('method', 'digitalExcelResultDownload');
    await scwin.tx_fn_DigitalExcelResultDown();
};
